-- Existing M13 entity schema; unchanged by M14 profile database isolation.
CREATE TABLE IF NOT EXISTS `categories` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `icon_url` TEXT, `display_order` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `catalog_books` (`id` TEXT NOT NULL, `title` TEXT NOT NULL, `author` TEXT NOT NULL, `description` TEXT NOT NULL, `cover_url` TEXT NOT NULL, `category_id` TEXT NOT NULL, `file_url` TEXT NOT NULL, `file_size_bytes` INTEGER NOT NULL, `content_version` INTEGER NOT NULL DEFAULT 1, `content_hash` TEXT, `is_featured` INTEGER NOT NULL, `is_new` INTEGER NOT NULL, `is_premium` INTEGER NOT NULL, `play_product_id` TEXT, `entitlement_type` TEXT NOT NULL, `rating` REAL NOT NULL, `published_date` TEXT, `updated_at` INTEGER NOT NULL, `format` TEXT NOT NULL DEFAULT 'EPUB', `media_type` TEXT NOT NULL DEFAULT 'application/epub+zip', `source_type` TEXT NOT NULL DEFAULT 'LOCAL_FILE', `source_url` TEXT, `is_in_inbox` INTEGER NOT NULL DEFAULT 0, `inbox_added_at` INTEGER, `is_pinned` INTEGER NOT NULL DEFAULT 0, `is_archived` INTEGER NOT NULL DEFAULT 0, `reading_status` TEXT NOT NULL DEFAULT 'UNREAD', `user_title_override` TEXT, `user_author_override` TEXT, `custom_cover_path` TEXT, `last_opened_at` INTEGER, `added_at` INTEGER NOT NULL DEFAULT 0, `original_filename` TEXT, PRIMARY KEY(`id`), FOREIGN KEY(`category_id`) REFERENCES `categories`(`id`) ON UPDATE NO ACTION ON DELETE RESTRICT );
CREATE INDEX IF NOT EXISTS `index_catalog_books_category_id` ON `catalog_books` (`category_id`);
CREATE INDEX IF NOT EXISTS `index_catalog_books_is_featured` ON `catalog_books` (`is_featured`);
CREATE INDEX IF NOT EXISTS `index_catalog_books_is_new` ON `catalog_books` (`is_new`);
CREATE INDEX IF NOT EXISTS `index_catalog_books_title` ON `catalog_books` (`title`);
CREATE INDEX IF NOT EXISTS `index_catalog_books_is_in_inbox` ON `catalog_books` (`is_in_inbox`);
CREATE INDEX IF NOT EXISTS `index_catalog_books_is_pinned` ON `catalog_books` (`is_pinned`);
CREATE INDEX IF NOT EXISTS `index_catalog_books_is_archived` ON `catalog_books` (`is_archived`);
CREATE INDEX IF NOT EXISTS `index_catalog_books_reading_status` ON `catalog_books` (`reading_status`);
CREATE TABLE IF NOT EXISTS `downloaded_books` (`book_id` TEXT NOT NULL, `local_file_path` TEXT NOT NULL, `download_status` TEXT NOT NULL, `download_progress` REAL NOT NULL, `downloaded_bytes` INTEGER NOT NULL, `total_bytes` INTEGER NOT NULL, `downloaded_content_version` INTEGER NOT NULL DEFAULT 1, `content_hash` TEXT, `downloaded_at` INTEGER, `last_error` TEXT, PRIMARY KEY(`book_id`), FOREIGN KEY(`book_id`) REFERENCES `catalog_books`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `reading_progress` (`book_id` TEXT NOT NULL, `locator_json` TEXT NOT NULL, `progression` REAL NOT NULL, `chapter_title` TEXT, `last_read_at` INTEGER NOT NULL, `sync_version` INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(`book_id`), FOREIGN KEY(`book_id`) REFERENCES `catalog_books`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `bookmarks` (`id` TEXT NOT NULL, `book_id` TEXT NOT NULL, `locator_json` TEXT NOT NULL, `chapter_title` TEXT NOT NULL, `snippet` TEXT, `created_at` INTEGER NOT NULL, `sync_version` INTEGER NOT NULL DEFAULT 1, `is_deleted` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`), FOREIGN KEY(`book_id`) REFERENCES `catalog_books`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_bookmarks_book_id` ON `bookmarks` (`book_id`);
CREATE INDEX IF NOT EXISTS `index_bookmarks_created_at` ON `bookmarks` (`created_at`);
CREATE TABLE IF NOT EXISTS `favorites` (`book_id` TEXT NOT NULL, `added_at` INTEGER NOT NULL, `sync_version` INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(`book_id`), FOREIGN KEY(`book_id`) REFERENCES `catalog_books`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `collections` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `sort_order` INTEGER NOT NULL DEFAULT 0, `sort_type` TEXT NOT NULL DEFAULT 'RECENTLY_ADDED', PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `book_collection_cross_ref` (`book_id` TEXT NOT NULL, `collection_id` TEXT NOT NULL, `added_at` INTEGER NOT NULL, PRIMARY KEY(`book_id`, `collection_id`), FOREIGN KEY(`book_id`) REFERENCES `catalog_books`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`collection_id`) REFERENCES `collections`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_book_collection_cross_ref_book_id` ON `book_collection_cross_ref` (`book_id`);
CREATE INDEX IF NOT EXISTS `index_book_collection_cross_ref_collection_id` ON `book_collection_cross_ref` (`collection_id`);
CREATE TABLE IF NOT EXISTS `highlights` (`id` TEXT NOT NULL, `book_id` TEXT NOT NULL, `locator_json` TEXT NOT NULL, `text` TEXT NOT NULL, `color` TEXT NOT NULL, `note` TEXT, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`book_id`) REFERENCES `catalog_books`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_highlights_book_id` ON `highlights` (`book_id`);
CREATE INDEX IF NOT EXISTS `index_highlights_created_at` ON `highlights` (`created_at`);
CREATE TABLE IF NOT EXISTS `per_book_preferences` (`book_id` TEXT NOT NULL, `theme` TEXT, `font_family` TEXT, `font_size` REAL, `line_height` REAL, `text_alignment` TEXT, `scroll_mode` INTEGER, `use_book_override` INTEGER NOT NULL DEFAULT 0, `updated_at` INTEGER NOT NULL, PRIMARY KEY(`book_id`), FOREIGN KEY(`book_id`) REFERENCES `catalog_books`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `custom_fonts` (`id` TEXT NOT NULL, `font_family` TEXT NOT NULL, `file_name` TEXT NOT NULL, `file_size` INTEGER NOT NULL, `created_at` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `tags` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `normalized_name` TEXT NOT NULL, `created_at` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `index_tags_normalized_name` ON `tags` (`normalized_name`);
CREATE TABLE IF NOT EXISTS `book_tag_cross_ref` (`book_id` TEXT NOT NULL, `tag_id` TEXT NOT NULL, `added_at` INTEGER NOT NULL, PRIMARY KEY(`book_id`, `tag_id`), FOREIGN KEY(`book_id`) REFERENCES `catalog_books`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`tag_id`) REFERENCES `tags`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_book_tag_cross_ref_book_id` ON `book_tag_cross_ref` (`book_id`);
CREATE INDEX IF NOT EXISTS `index_book_tag_cross_ref_tag_id` ON `book_tag_cross_ref` (`tag_id`);
CREATE TABLE IF NOT EXISTS `review_items` (`id` TEXT NOT NULL, `annotation_id` TEXT NOT NULL, `book_id` TEXT NOT NULL, `is_enabled` INTEGER NOT NULL DEFAULT 1, `next_review_at` INTEGER NOT NULL, `last_reviewed_at` INTEGER, `review_count` INTEGER NOT NULL DEFAULT 0, `interval_days` INTEGER NOT NULL DEFAULT 1, `ease_factor` REAL NOT NULL DEFAULT 2.5, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`annotation_id`) REFERENCES `highlights`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`book_id`) REFERENCES `catalog_books`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE UNIQUE INDEX IF NOT EXISTS `index_review_items_annotation_id` ON `review_items` (`annotation_id`);
CREATE INDEX IF NOT EXISTS `index_review_items_book_id` ON `review_items` (`book_id`);
CREATE INDEX IF NOT EXISTS `index_review_items_next_review_at` ON `review_items` (`next_review_at`);
CREATE INDEX IF NOT EXISTS `index_review_items_is_enabled` ON `review_items` (`is_enabled`);
CREATE TABLE IF NOT EXISTS `reading_sessions` (`id` TEXT NOT NULL, `book_id` TEXT NOT NULL, `started_at` INTEGER NOT NULL, `ended_at` INTEGER, `duration_ms` INTEGER NOT NULL DEFAULT 0, `start_progress` REAL NOT NULL DEFAULT 0.0, `end_progress` REAL NOT NULL DEFAULT 0.0, `format` TEXT NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`book_id`) REFERENCES `catalog_books`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_reading_sessions_book_id` ON `reading_sessions` (`book_id`);
CREATE INDEX IF NOT EXISTS `index_reading_sessions_started_at` ON `reading_sessions` (`started_at`);
